function inside_board_list(int $boardNo, int $page, ?int $categoryNo = null, ?string $q = null): array
{
    $sitekey = inside_board_sitekey();
    $perPage = inside_board_per_page($boardNo);
    $page = max(1, $page);
    $offset = ($page - 1) * $perPage;

    $where = 'a.sitekey = :sitekey AND a.board_no = :board_no';
    $params = [
        ':sitekey' => $sitekey,
        ':board_no' => $boardNo,
    ];

    if ($categoryNo !== null && $categoryNo > 0) {
        $where .= ' AND a.category_no = :category_no';
        $params[':category_no'] = $categoryNo;
    }

    $qTrim = $q !== null ? trim($q) : '';
    if ($qTrim !== '') {
        $like = '%' . $qTrim . '%';
        $where .= ' AND (a.title LIKE :like_title OR a.contents LIKE :like_contents)';
        $params[':like_title'] = $like;
        $params[':like_contents'] = $like;
    }

    $db = DB::getInstance();

    $countSql = "SELECT COUNT(*) AS cnt FROM nb_board a WHERE {$where}";
    $cstmt = $db->prepare($countSql);
    foreach ($params as $k => $v) {
        $cstmt->bindValue($k, $v);
    }
    $cstmt->execute();
    $totalRows = (int) ($cstmt->fetch(PDO::FETCH_ASSOC)['cnt'] ?? 0);

