$router->get('/sitemap.xml', function () {
    $db = Database\DB::getInstance();

    $worksRows = $db->query(
        "SELECT no, updated_at FROM nb_works WHERE is_display = 'Y' AND is_deleted = 'N' ORDER BY no DESC"
    )->fetchAll(PDO::FETCH_ASSOC);

    $newsRows = $db->query(
        "SELECT no, regdate FROM nb_board WHERE board_no = " . INSIDE_BOARD_NEWS . " AND is_deleted = 'N' ORDER BY no DESC"
    )->fetchAll(PDO::FETCH_ASSOC);

    $insightRows = $db->query(
        "SELECT no, regdate FROM nb_board WHERE board_no = " . INSIDE_BOARD_INSIGHT . " AND is_deleted = 'N' ORDER BY no DESC"
    )->fetchAll(PDO::FETCH_ASSOC);

    $xml = view('pages.sitemap', [
        'worksRows'   => $worksRows,
        'newsRows'    => $newsRows,
        'insightRows' => $insightRows,
    ])->setLayout(null)->render();

    $res = response($xml);
    $res->header('Content-Type', 'application/xml; charset=utf-8');
    return $res;
})->name('sitemap.xml');

